// v0.4-split: Object loading, fetchJson, and URL auto-load runtime
// Generated by responsibility split. No functional change intended.

async function loadFromObjects(defObj, dataObj, label='読み込み完了', dataApiUrl=null, dataDisplayPath=null, dataSourceKind='data') {
  defObj = await resolveFieldTypesForViewDef(defObj);
  currentViewDefReadContract = (typeof extractViewDefReadContract === 'function')
    ? extractViewDefReadContract(defObj)
    : null;
  currentViewDefContextModel = (typeof extractViewDefContextModel === 'function')
    ? extractViewDefContextModel(defObj)
    : null;
  mainContextPanelExpanded = false;
  targetContextDetailPanelExpanded = false;
  if (typeof logViewDefReadContract === 'function') logViewDefReadContract(currentViewDefReadContract);
  if (typeof logViewDefContextModel === 'function') logViewDefContextModel(currentViewDefContextModel);
  viewDef = defObj;
  if (typeof loadRuntimeFieldDefinitionContext === 'function') {
    await loadRuntimeFieldDefinitionContext(defObj);
  }
  currentDataSources = {};
  currentDataSourceSpecs = {};
  sourceData = await materializeVirtualDataForViewDef(defObj, dataObj);

  if (!isDefCompatibleWithData(defObj, sourceData)) {
    throw new Error(defCompatibilityMessage(lastLoadedDefName, defObj, sourceData));
  }
  selectedIndex = -1;
  sortState = { field: null, direction: null };
  copiedRow = null;
  detailMode = 'edit';
  draftRow = null;
  currentDataApiUrl = dataApiUrl;
  currentDataSourceKind = dataSourceKind === 'viewdef' ? 'viewdef' : 'data';
  if (currentDataSourceKind !== 'viewdef') currentViewDefMaintenanceTarget = '';
  if (lastLoadedDefName && $('defNameInput')) $('defNameInput').value = lastLoadedDefName;
  renderByKey('header');
  renderByKey('search');
  loadRows();
  renderByKey('grid');
  renderByKey('viewExecuteButton');
  if (typeof renderRelatedGridLaunchButtons === 'function') renderRelatedGridLaunchButtons();
  $('saveBtn').disabled = false;
  if ($('gridCsvExportBtn')) $('gridCsvExportBtn').disabled = false;
  if ($('exportMarkdownBtn')) $('exportMarkdownBtn').disabled = false;
  if (typeof updateMarkdownExportModeSelect === 'function') updateMarkdownExportModeSelect();
  updateViewDefMarkdownButtonState();
  if ($('exportViewDefMarkdownBtn')) $('exportViewDefMarkdownBtn').disabled = false;
  $('saveBtn').textContent = currentDataApiUrl ? '上書き保存' : '別名保存';
  const mainGridIsVirtual = isVirtualDataCompatible(defObj, gridDef());
  $('addRowBtn').disabled = mainGridIsVirtual;
  $('deleteRowBtn').disabled = mainGridIsVirtual;
  updateReadonlyLaunchControls();
  updateFileLabels();
  if (typeof setCurrentLoadedDataDisplayPath === 'function') {
    setCurrentLoadedDataDisplayPath(dataDisplayPath || dataApiUrl || label, { updateStatus: false });
  }
  if (typeof updateCurrentLoadedDataTitleFromViewDef === 'function') {
    updateCurrentLoadedDataTitleFromViewDef(defObj, sourceData);
  }
  const loadedStatusText = (typeof currentLoadedDataStatusText === 'function') ? currentLoadedDataStatusText() : '';
  setStatus(loadedStatusText || label, { toast: false, sticky: true });
}

async function loadFromFiles() {
  launchRuntime = { fromUrl: false, mode: '', readonly: false, dataParam: '', viewParam: '', fileParam: '' };
  await loadFromDroppedFilesOrServer();
}

async function fetchJson(url) {
  const res = await fetch(url, {cache: 'no-store'});
  if (!res.ok) throw new Error(`${url} の読み込みに失敗しました (${res.status})`);
  return res.json();
}

function normalizeRuntimeFieldDefinitionRef(raw) {
  const value = String(raw ?? '').trim().replace(/\\/g, '/');
  if (!value) return '';
  if (value.includes('://') || value.startsWith('/') || /^[A-Za-z]:/.test(value) || /[?#]/.test(value)) {
    throw new Error(`item_definition_ref が不正です: ${value}`);
  }
  if (!value.toLowerCase().endsWith('.json')) {
    throw new Error(`item_definition_ref は .json を指定してください: ${value}`);
  }
  const parts = value.split('/');
  if (parts.some(part => !part || part === '.' || part === '..')) {
    throw new Error(`item_definition_ref のパスが不正です: ${value}`);
  }
  return parts.join('/');
}

function runtimeFieldDefinitionApiPath(ref) {
  return '/api/fielddefs/' + ref.split('/').map(part => encodeURIComponent(part)).join('/');
}

async function loadRuntimeFieldDefinitionContext(defObj) {
  currentRuntimeFieldDefinitionRef = '';
  currentRuntimeFieldDefinitionDocument = null;
  currentRuntimeValidationTypeRegistry = null;

  const ref = normalizeRuntimeFieldDefinitionRef(
    defObj?.item_definition_ref
      ?? defObj?.itemDefinitionRef
      ?? ''
  );
  if (!ref) return { enabled: false };

  const registryPath = '/api/data/config/validation_type_registry_v0_1.json';
  let fieldDefinitionDocument;
  let registry;
  try {
    [fieldDefinitionDocument, registry] = await Promise.all([
      fetchJson(runtimeFieldDefinitionApiPath(ref)),
      fetchJson(registryPath)
    ]);
  } catch (err) {
    throw new Error(`Field Definition Runtime契約の読み込みに失敗しました: ${ref} / ${err.message}`);
  }

  if (fieldDefinitionDocument?.document_type !== 'field_definition' || !Array.isArray(fieldDefinitionDocument?.field_definitions)) {
    throw new Error(`item_definition_ref のJSONがField Definition契約ではありません: ${ref}`);
  }
  if (registry?.document_type !== 'validation_type_registry' || !Array.isArray(registry?.validation_type_definitions)) {
    throw new Error(`Validation Type Registryが不正です: config/validation_type_registry_v0_1.json`);
  }

  currentRuntimeFieldDefinitionRef = ref;
  currentRuntimeFieldDefinitionDocument = fieldDefinitionDocument;
  currentRuntimeValidationTypeRegistry = registry;
  return {
    enabled: true,
    ref,
    field_definition_count: fieldDefinitionDocument.field_definitions.length,
    registry_version: String(registry.registry_version ?? '')
  };
}


function isLaunchReadonlyMode(mode) {
  return String(mode ?? '').trim().toLowerCase() === 'readonly';
}


function launchParamsObject(params) {
  const obj = {};
  try {
    params.forEach((value, key) => { obj[key] = value; });
  } catch { /* ignore */ }
  return obj;
}

function normalizeLaunchActionId(raw) {
  const v = String(raw ?? '').trim();
  if (!v) return '';
  const lower = v.toLowerCase();
  if (['fx_chart', 'fxchart', 'chart', 'open_fx_chart', 'openfxt3chart', 'openfxchartviewer', 'fxt3chart'].includes(lower)) {
    return 'OpenFxT3Chart';
  }
  return v;
}

async function executeLaunchActionFromQuery(params) {
  const rawAction = params.get('action') || params.get('autoAction') || params.get('open');
  const actionId = normalizeLaunchActionId(rawAction);
  if (!actionId) return;
  if (typeof executeStudioAction !== 'function' || typeof currentStudioActionContext !== 'function') {
    throw new Error(`URL action を実行できません。ActionRegistryが未初期化です: ${actionId}`);
  }
  const context = currentStudioActionContext({
    launchParams: launchParamsObject(params),
    urlParams: launchParamsObject(params)
  });
  const result = await executeStudioAction(actionId, context);
  if (result?.message && typeof setStatus === 'function') {
    setStatus(result.message, { kind: result.status_kind || 'success', title: result.status_title || 'URL Action' });
  }
}

// v0.18.24-thought-evolution-studio-v0-2-relation-approval:
// Overlayのresource_refからStudio標準エディターへ遷移したとき、
// 指定された原本レコードを選択してDetailを開くためのURL focus契約。
function normalizeLaunchFocusField(raw) {
  const field = String(raw ?? '').trim();
  if (!field) return '';
  if (!/^[A-Za-z0-9_$.[\]-]+$/.test(field)) return '';
  return field;
}

function launchBooleanParam(params, name, fallback=false) {
  const raw = String(params.get(name) ?? '').trim().toLowerCase();
  if (!raw) return fallback;
  return ['1', 'true', 'yes', 'on', 'open'].includes(raw);
}

function applyLaunchFocusFromQuery(params) {
  const focusField = normalizeLaunchFocusField(
    params.get('focusField') || params.get('recordField') || params.get('rowField')
  );
  const focusValue = params.get('focusValue') ?? params.get('recordId') ?? params.get('rowId');
  if (!focusField || focusValue == null || focusValue === '') return false;
  if (!Array.isArray(currentRows)) return false;

  const target = String(focusValue);
  const index = currentRows.findIndex(row => String(getByPath(row, focusField) ?? '') === target);
  if (index < 0) {
    setStatus(`URL focus対象が見つかりません: ${focusField}=${target}`, {
      kind: 'warn', title: '標準エディターFocus', toast: false
    });
    return false;
  }

  selectedIndex = index;
  renderByKey('grid');
  const openDetailRequested = launchBooleanParam(params, 'openDetail', true);
  if (openDetailRequested && typeof openDetail === 'function') openDetail(index);
  setStatus(`URL focus: ${focusField}=${target}`, {
    kind: 'success', title: '標準エディターFocus', toast: false
  });
  return true;
}


function updateReadonlyLaunchControls() {
  const readonly = Boolean(launchRuntime?.readonly);
  const idsToDisable = [
    'saveBtn',
    'addRowBtn',
    'deleteRowBtn',
    'applyDetailBtn',
    'pasteCopiedBtn'
  ];
  idsToDisable.forEach(id => {
    const el = $(id);
    if (el) el.disabled = readonly || el.disabled;
  });

  if (readonly) {
    const saveBtn = $('saveBtn');
    if (saveBtn) saveBtn.textContent = 'ReadOnly';
  }
}

function normalizeLaunchJsonPath(raw, label) {
  const value = String(raw ?? '').trim();
  if (!value) return null;
  const decoded = value.replace(/\\/g, '/');
  if (decoded.includes('://') || decoded.startsWith('//')) {
    throw new Error(`${label} に外部URLは指定できません: ${value}`);
  }
  if (decoded.startsWith('/')) {
    throw new Error(`${label} に絶対パスは指定できません: ${value}`);
  }
  if (/^[a-zA-Z]:/.test(decoded)) {
    throw new Error(`${label} にローカルドライブパスは指定できません: ${value}`);
  }
  if (/[?#]/.test(decoded)) {
    throw new Error(`${label} にクエリ文字列やハッシュは指定できません: ${value}`);
  }
  if (!decoded.toLowerCase().endsWith('.json')) {
    throw new Error(`${label} は .json を指定してください: ${value}`);
  }
  const parts = decoded.split('/');
  if (parts.some(part => !part || part === '.' || part === '..')) {
    throw new Error(`${label} のパスが不正です: ${value}`);
  }
  return parts.join('/');
}

function staticJsonKindPath(path, kind) {
  if (!path) return null;
  const prefix = kind === 'data' ? 'data/' : 'defs/';
  if (!path.startsWith(prefix)) return null;
  return path.slice(prefix.length);
}

function launchApiNameFromStaticPath(path, kind) {
  const rel = staticJsonKindPath(path, kind);
  return rel ? safeJsonFileName(rel) : null;
}

async function fetchLaunchDataJson(rawPath) {
  const path = normalizeLaunchJsonPath(rawPath, 'data');
  const managedName = launchApiNameFromStaticPath(path, 'data');

  if (managedName) {
    return {
      json: await fetchJson(path),
      dataName: managedName,
      dataApiUrl: isStaticHostingMode() ? null : apiJsonUrl('data', managedName),
      displayPath: path
    };
  }

  const loaded = await fetchApiJsonWithUrl('data', path);
  const dataName = loaded.correctedName || jsonNameFromUrl(loaded.url, 'data') || safeJsonFileName(path);
  return {
    json: loaded.json,
    dataName,
    dataApiUrl: normalizeApiDataUrl(loaded.url),
    displayPath: loaded.url
  };
}

async function fetchLaunchViewDefJson(rawPath) {
  const path = normalizeLaunchJsonPath(rawPath, 'view');
  const managedName = launchApiNameFromStaticPath(path, 'defs');

  if (managedName) {
    const rawDefObj = await fetchJson(path);
    return {
      defName: managedName,
      defObj: await resolveViewDefInheritance(rawDefObj, managedName),
      displayPath: path
    };
  }

  const defName = safeJsonFileName(path);
  if (!defName) throw new Error(`view のパスが不正です: ${rawPath}`);
  return {
    defName,
    defObj: await fetchResolvedViewDef(defName),
    displayPath: path
  };
}

function launchStatusSuffix() {
  return launchRuntime?.readonly ? ' / ReadOnly' : '';
}

async function autoLoadFromQuery() {
  const params = new URLSearchParams(location.search);
  if (typeof isRelatedGridLaunchQuery === 'function' && isRelatedGridLaunchQuery(params)) {
    try {
      await initializeRelatedGridChildFromQuery(params);
    } catch (err) {
      console.error(err);
      if (typeof setRelatedGridShellStatus === 'function') {
        setRelatedGridShellStatus(`初期化エラー: ${err.message}`, 'error');
      }
      setStatus('別Grid起動エラー: ' + err.message, { kind: 'error', title: '別Grid起動エラー', sticky: true });
    }
    return;
  }
  const viewParam = params.get('view') || params.get('def');
  const dataParam = params.get('data');
  const mode = params.get('mode') || '';

  if (!viewParam && !dataParam && !mode) return;

  launchRuntime = {
    fromUrl: Boolean(viewParam || dataParam),
    mode,
    readonly: isLaunchReadonlyMode(mode),
    dataParam: dataParam || '',
    viewParam: viewParam || '',
    fileParam: ''
  };

  try {
    if (!dataParam) {
      if (viewParam) throw new Error('URL起動では data パラメータを指定してください');
      return;
    }
    if ($('defFileName')) $('defFileName').textContent = viewParam || '(data内 view_def)';
    if ($('dataFileName')) $('dataFileName').textContent = dataParam;
    console.log('[FRBStudio load] URLパラメータから読み込み中...');

    const loadedData = await fetchLaunchDataJson(dataParam);
    const dataObj = loadedData.json;
    const dataName = loadedData.dataName;
    if (dataName && $('dataNameInput')) $('dataNameInput').value = dataName;
    updateCurrentDataViewDefCandidates(dataObj, dataName);

    let defName = null;
    let defObj = null;
    let autoMsg = '';

    if (viewParam) {
      const loadedDef = await fetchLaunchViewDefJson(viewParam);
      defName = loadedDef.defName;
      if (!isViewDefCandidateAllowedForData(dataObj, defName)) {
        const allowed = getDataViewDefCandidateItems(dataObj).map(item => item.view_def).join(' / ') || '(候補なし)';
        throw new Error(`URLの view パラメータ「${defName}」は、このData JSONの view_def / view_def_candidates に含まれていません。候補: ${allowed}`);
      }
      defObj = loadedDef.defObj;
      if (!isDefCompatibleWithData(defObj, dataObj)) {
        throw new Error(defCompatibilityMessage(defName, defObj, dataObj, dataName) + '。URLの view パラメータを確認してください');
      }
    } else {
      const resolved = await resolveDefForData(null, dataObj, dataName);
      defName = resolved.defName;
      defObj = resolved.defObj;
      autoMsg = resolved.previousDefName
        ? ` / 画面定義を自動補正: ${resolved.previousDefName} → ${defName}`
        : (resolved.autoChanged ? ` / 画面定義を自動選択: ${defName}` : '');
    }

    lastLoadedDefName = defName;
    if (defName && $('defNameInput')) $('defNameInput').value = defName;
    ensureViewDefNameInData(dataObj, defName);

    const saveUrl = launchRuntime.readonly ? null : loadedData.dataApiUrl;
    await loadFromObjects(
      defObj,
      dataObj,
      `URLパラメータから読み込み完了: ${dataName || dataParam}${autoMsg}${launchStatusSuffix()}`,
      saveUrl,
      loadedData.displayPath || dataName || dataParam
    );

    applyLaunchFocusFromQuery(params);
    await executeLaunchActionFromQuery(params);
  } catch (err) {
    console.error(err);
    setStatus('URL読込エラー: ' + err.message + '（file://直開きの場合はローカルサーバ起動が必要な場合があります）', { kind: 'error', title: 'URL読込エラー' });
  }
}

